window.LIB_LAZY=window.LIB_LAZY||{};
window.LIB_LAZY["eusebiu-istoria#248"]=[{"v":1,"t":"Mulțumire pentru toate să fie dată lui Dumnezeu, Stăpânitorul Atotțiitor și Împăratul universului, și cea mai mare mulțumire lui Isus Hristos, Mântuitorul și Răscumpărătorul sufletelor noastre, prin care ne rugăm ca pacea să ne fie păstrată totdeauna fermă și netulburată de necazurile din afară și de necazurile minții."},{"v":2,"t":"Fiindcă, potrivit dorințelor tale, prea sfinte Paulin, am adăugat cartea a zecea a Istoriei Bisericii la cele dinainte, ți-o vom închina ție, proclamându-te pecetea întregii lucrări; și vom adăuga potrivit, într-un număr desăvârșit, desăvârșita cuvântare de laudă despre restaurarea bisericilor, ascultând de Duhul dumnezeiesc care ne îndeamnă în aceste cuvinte:"},{"v":3,"t":"„Cântați Domnului o cântare nouă, căci a făcut lucruri minunate. Dreapta Lui și brațul Lui cel sfânt L-au mântuit. Domnul a făcut cunoscută mântuirea Sa, dreptatea Sa a descoperit-o înaintea neamurilor.”"},{"v":4,"t":"Și potrivit zicerii care ne poruncește să cântăm cântarea cea nouă, să mergem mai departe arătând că, după acele spectacole cumplite și sumbre pe care le-am descris, ni se îngăduie acum să vedem și să sărbătorim asemenea lucruri pe care mulți oameni cu adevărat drepți și martiri ai lui Dumnezeu înaintea noastră au dorit să le vadă pe pământ și nu le-au văzut, și să le audă și nu le-au auzit. (Matei 13:17)"},{"v":5,"t":"Dar ei, grăbindu-se, au dobândit lucruri mult mai bune, fiind duși în cer și în raiul desfătării dumnezeiești. Dar recunoscând că și acestea sunt mai mari decât merităm, ne-am mirat de harul arătat de autorul marilor daruri și pe bună dreptate îl admirăm, închinându-ne Lui cu toată puterea sufletelor noastre și mărturisind adevărul acelor zicere înregistrate, în care se spune: „Veniți și vedeți lucrările Domnului, minunile pe care le-a făcut pe pământ; El pune capăt războaielor până la marginile lumii, va frânge arcul și va zdrobi sulița și va arde scuturile în foc.”"},{"v":6,"t":"Bucurându-ne de aceste lucruri care s-au împlinit limpede în zilele noastre, să mergem mai departe cu relatarea noastră."},{"v":7,"t":"Tot neamul dușmanilor lui Dumnezeu a fost nimicit în chipul arătat și a fost astfel măturat deodată din fața oamenilor. Așa încât o zicere dumnezeiască a avut din nou împlinirea ei: „Am văzut pe cel nelegiuit mult înălțat și ridicându-se ca cedrii Libanului și am trecut, și iată, nu mai era, și l-am căutat și locul lui nu s-a mai găsit.”"},{"v":8,"t":"Și în cele din urmă o zi strălucitoare și luminoasă, neumbrită de niciun nor, a luminat cu raze de lumină cerească bisericile lui Hristos de pe tot pământul. Și nici cei din afara comuniunii noastre nu au fost împiedicați să aibă parte de aceleași binecuvântări sau cel puțin să vină sub influența lor și să se bucure de o parte din binefacerile pe care ni le-a dat Dumnezeu."}];
window.LIB_LAZY["eusebiu-istoria#249"]=[{"v":1,"t":"Toți oamenii au fost, deci, eliberați de asuprirea tiranilor și, scăpați de relele de mai înainte, unul într-un chip și altul în altul au recunoscut pe apărătorul celor cucernici ca singurul Dumnezeu adevărat. Și noi mai ales, care ne puseserăm nădejdile în Hristosul lui Dumnezeu, am avut o bucurie de nespus și o anumită veselie insuflată a înflorit pentru noi toți, când am văzut fiecare loc care, cu puțin înainte, fusese pustiit de nelegiuirile tiranilor, înviind ca dintr-o lungă ciumă aducătoare de moarte, și temple ridicându-se iarăși din temelii la o înălțime imensă și primind o strălucire cu mult mai mare decât a celor vechi care fuseseră nimicite."},{"v":2,"t":"Dar și stăpânitorii supremi ne-au întărit și mai pe larg darnicia lui Dumnezeu prin rânduieli repetate în favoarea creștinilor; și scrisori personale ale împăratului au fost trimise episcopilor, cu onoruri și daruri de bani. Poate nu este nepotrivit să inserăm aceste documente, traduse din limba romană în greacă, la locul potrivit în această carte, ca pe o tăbliță sfântă, ca să rămână ca amintire pentru toți cei ce vor veni după noi."}];
window.LIB_LAZY["eusebiu-istoria#250"]=[{"v":1,"t":"După aceasta s-a văzut priveliștea dorită și cerută în rugăciune de noi toți; au avut loc sărbători de sfințire în cetăți și consacrări ale caselor de rugăciune nou zidite, episcopii s-au adunat, străinii au venit laolaltă de peste hotare, iubirea dintre popor și popor s-a arătat, membrele trupului lui Hristos s-au unit într-o deplină armonie."},{"v":2,"t":"Atunci s-a împlinit zicerea proorocească, care prevestise tainic ce urma să se petreacă: „Os la os și încheietură la încheietură” (Ezechiel 37:7) și tot ce a fost vestit cu adevărat în expresii enigmatice în pasajul insuflat."},{"v":3,"t":"Și era o singură lucrare a Duhului dumnezeiesc străbătând toate mădularele, și un suflet în toți, și aceeași râvnă a credinței, și un singur imn din partea tuturor spre lauda Dumnezeirii. Ba chiar slujbe desăvârșite erau săvârșite de arhierei, riturile sfinte fiind săvârșite solemn și rânduielile maiestuoase ale Bisericii păzite, aici cu cântarea psalmilor și cu citirea cuvintelor încredințate nouă de Dumnezeu, și dincolo cu săvârșirea slujbelor dumnezeiești și tainice; și simbolurile tainice ale patimii Mântuitorului erau împărțite."},{"v":4,"t":"În același timp, oameni de orice vârstă, atât bărbați, cât și femei, cu toată puterea minții dădeau cinste lui Dumnezeu, făcătorul binefacerilor lor, în rugăciuni și mulțumiri, cu minte și suflet bucuros. Și fiecare dintre episcopii de față, fiecare după puterea lui, rostea cuvântări de laudă, adăugând strălucire adunării."}];
window.LIB_LAZY["eusebiu-istoria#251"]=[{"v":1,"t":"Un oarecare dintre cei cu talent mijlociu, care alcătuise o cuvântare, s-a ridicat în prezența multor păstori adunați ca la o adunare bisericească și, pe când ei ascultau liniștit și cuviincios, s-a adresat în chipul următor celui care era în toate un episcop prea ales și iubit de Dumnezeu, prin a cărui râvnă fusese ridicat templul din Tir, cel mai strălucit din Fenicia. Cuvântare de laudă despre zidirea bisericilor, adresată lui Paulin, episcopul Tirului."},{"v":2,"t":"Prieteni și preoți ai lui Dumnezeu, îmbrăcați în veșmântul sfânt și împodobiți cu cununa cerească a slavei, cu ungerea insuflată și haina preoțească a Duhului Sfânt; și tu, mândrie a noului sfânt templu al lui Dumnezeu, înzestrat de El cu înțelepciunea vârstei, și totuși arătând lucrări și fapte scumpe ale unei virtuți tinere și înfloritoare, căruia Dumnezeu însuși, care cuprinde toată lumea, ți-a dat cinstea deosebită de a zidi și a înnoi această casă pământească pentru Hristos, Cuvântul Său Unul-Născut și Întâi-Născut, și pentru sfânta și dumnezeiasca Lui mireasă; —"},{"v":3,"t":"te-ar putea numi cineva un nou Beseleel, arhitectul unui cort dumnezeiesc, sau Solomon, împăratul unui nou și mult mai bun Ierusalim, sau și un nou Zorobabel, care a adăugat o slavă mult mai mare decât cea de mai înainte templului lui Dumnezeu; —"},{"v":4,"t":"și voi de asemenea, o, odrasle ale sfintei turme a lui Hristos, locaș al cuvintelor bune, școală a înțelepciunii și auditoriu august și cucernic al religiei:"},{"v":5,"t":"Ni s-a îngăduit de demult să înălțăm imnuri și cântări lui Dumnezeu, când am aflat, ascultând citirea dumnezeieștilor Scripturi, semnele minunate ale lui Dumnezeu și binefacerile revărsate asupra oamenilor prin faptele minunate ale Domnului, fiind învățați să zicem: «O, Dumnezeule! Am auzit cu urechile noastre, părinții noștri ne-au povestit lucrarea pe care ai făcut-o în zilele lor, în zilele de demult.»"},{"v":6,"t":"Dar acum, când nu mai zărim brațul înalt și dreapta cerească a prea binevoitorului nostru Dumnezeu și Împărat al universului doar din auzite sau din vorbă, ci vedem, ca să zic așa, în însăși faptă și cu ochii noștri, că cele spuse mai de mult sunt credincioase și adevărate, ni se îngăduie să înălțăm un al doilea imn de biruință și să cântăm cu glas tare și să spunem: «Precum am auzit, așa am văzut, în cetatea Domnului Savaot, în cetatea Dumnezeului nostru.»"},{"v":7,"t":"Și în ce cetate, dacă nu în aceasta nou zidită și făcută de Dumnezeu, care este «biserica Dumnezeului celui viu, stâlp și temelie a adevărului» (1 Timotei 3:15), despre care un alt oracol dumnezeiesc vestește astfel: «Lucruri slăvite s-au spus despre tine, cetate a lui Dumnezeu.» Fiindcă prea binevoitorul Dumnezeu ne-a adus laolaltă la ea, prin harul Unuia-Născut al Său, să cânte cu glas tare fiecare dintre cei chemați și să spună: «M-am bucurat când mi-au zis: Vom merge la casa Domnului», și «Doamne, am iubit frumusețea casei Tale și locul în care sălășluiește slava Ta.»"},{"v":8,"t":"Și să nu-L cinstim numai unul câte unul, ci toți împreună, cu un singur duh și un singur suflet, și să strigăm, zicând: «Mare este Domnul și lăudat foarte în cetatea Dumnezeului nostru, în muntele Lui cel sfânt.» Căci cu adevărat este mare și mare este casa Lui, înaltă și încăpătoare și «frumoasă în frumusețe mai presus de fiii oamenilor». «Mare este Domnul, care singur face minuni»; «mare este Cel ce face lucruri mari și de nepătruns, slăvite și minunate, care nu pot fi numărate» (Iov 9:10); mare este Cel ce «schimbă vremile și anotimpurile, care înalță și coboară împărații» (Daniel 2:21); «care ridică pe sărac din pământ și înalță pe cel lipsit din gunoi». «A coborât pe cei puternici de pe tronuri și a înălțat pe cei smeriți de pe pământ. Pe cei flămânzi i-a umplut de bunătăți și brațele celor mândri le-a zdrobit.» (Luca 1:52-53)"},{"v":9,"t":"Nu numai credincioșilor, ci și necredincioșilor le-a întărit relatarea întâmplărilor vechi; Cel ce face minuni, Cel ce face lucruri mari, Stăpânul tuturor, Făcătorul întregii lumi, Atotputernicul, Preamilostivul, unicul Dumnezeu. Lui să-I cântăm cântarea cea nouă, adăugând în gând: «Celui ce singur face minuni mari, căci în veac este mila Lui»; «Celui ce a lovit împărați mari și a omorât împărați vestiți, căci în veac este mila Lui»; «Căci Domnul și-a adus aminte de noi în smerenia noastră și ne-a izbăvit de potrivnicii noștri.»"},{"v":10,"t":"Și să nu încetăm niciodată să strigăm aceste cuvinte către Tatăl universului. Și să-L cinstim totdeauna cu gura pe Cel ce este a doua pricină a binefacerilor noastre, învățătorul cunoașterii dumnezeiești, dascălul adevăratei religii, nimicitorul celor nelegiuiți, ucigătorul tiranilor, îndreptătorul vieții, Isus, Mântuitorul nostru, al celor ce eram în deznădejde."},{"v":11,"t":"Căci numai El, ca singurul Fiu prea binevoitor al unui Tată prea binevoitor, potrivit planului bunăvoinței Tatălui Său, a luat de bunăvoie firea noastră, a celor care zăceam în stricăciune, și ca un doctor ales, care pentru mântuirea celor bolnavi le cercetează suferințele, le atinge rănile urâte și culege durere pentru sine din nenorocirile altuia, tot astfel pe noi, care nu eram numai bolnavi și chinuiți de răni cumplite și plăgi deja putrezite, ci chiar zăceam printre cei morți, ne-a mântuit pentru Sine chiar din fălcile morții. Căci niciunul altul dintre cei din ceruri nu avea o asemenea putere încât să slujească fără vătămare mântuirii atâtora."},{"v":12,"t":"Dar numai El, ajungând la adâncul nostru de stricăciune, numai El luând asupra Lui ostenelile noastre, numai El suferind pedepsele datorate nelegiuirilor noastre, redobândind pe noi, care nu eram doar pe jumătate morți, ci eram deja în morminte și sicrie, și cu totul urâți și scârboși, ne mântuiește, atât din vechime, cât și acum, prin râvna Lui binefăcătoare, dincolo de așteptarea oricui, chiar a noastră, și împărtășește din belșug din binefacerile Tatălui — El, care este dătătorul vieții și al luminii, marele nostru Doctor și Împărat și Domn, Hristosul lui Dumnezeu."},{"v":13,"t":"Căci atunci când tot neamul omenesc zăcea îngropat în noapte sumbră și în adâncuri de întuneric prin meșteșugurile înșelătoare ale demonilor vinovați și prin puterea duhurilor vrăjmașe lui Dumnezeu, prin simpla Lui arătare a dezlegat o dată pentru totdeauna funiile strâns legate ale nelegiuirilor noastre prin razele luminii Lui, precum se topește ceara."},{"v":14,"t":"Dar când invidia răutăcioasă și demonul iubitor de rău aproape că au plesnit de mânie pentru un asemenea har și o asemenea bunătate și și-au întors împotriva noastră toate forțele lor aducătoare de moarte, și când, la început, ca un câine înnebunit care scrâșnește din dinți la pietrele aruncate în el și își varsă furia împotriva celor ce-l atacă pe proiectilele neînsuflețite, și-a îndreptat nebunia sălbatică spre pietrele locașurilor sfinte și spre materialul neînsuflețit al caselor și a pustiit bisericile, — cel puțin așa socotea — și apoi a scos șuierături cumplite și sunete ca de șarpe, când prin amenințările tiranilor nelegiuiți, când iarăși prin edictele hulitoare ale stăpânitorilor profani, vărsând moarte, pe lângă aceasta, și infectând cu otrăvurile lui vătămătoare și pierzătoare de suflete sufletele prinse de el, și aproape omorându-le prin jertfele lui aducătoare de moarte ale idolilor morți, și făcând ca orice fiară în chip de om și orice fel de sălbatic să ne atace — atunci, într-adevăr, «Îngerul sfatului celui mare», marele Căpitan al lui Dumnezeu, după ce cei mai viteji ostași ai împărăției Lui arătaseră destulă exersare prin răbdare și îndurare în toate, s-a arătat deodată din nou și a șters și a nimicit pe dușmanii și vrăjmașii Lui, așa încât păreau că nu au avut niciodată nici măcar un nume."},{"v":15,"t":"Dar pe prietenii și rudele Lui i-a înălțat la cea mai înaltă slavă, înaintea nu numai a tuturor oamenilor, ci și a puterilor cerești, a soarelui și lunii și stelelor și a întregului cer și pământ, așa încât acum, cum nu s-a mai întâmplat niciodată, stăpânitorii supremi, conștienți de onoarea pe care au primit-o de la El, scuipă în fețele idolilor morți, calcă în picioare riturile nesfințite ale demonilor, își bat joc de străvechea amăgire primită de la părinții lor și nu recunosc decât un singur Dumnezeu, binefăcătorul comun al tuturor, inclusiv al lor."},{"v":16,"t":"Și Îl mărturisesc pe Hristos, Fiul lui Dumnezeu, Împăratul universal al tuturor, și Îl proclamă Mântuitor pe monumente, înregistrând nepieritor în scrisori imperiale, în mijlocul cetății care stăpânește pământul, faptele Lui drepte și biruințele Lui asupra celor nelegiuiți. Astfel Isus Hristos, Mântuitorul nostru, este singurul din toată veșnicia care a fost recunoscut, chiar de cei mai înalți de pe pământ, nu ca un împărat obișnuit între oameni, ci ca adevărat fiu al Dumnezeului universal, și care a fost adorat ca Dumnezeu adevărat și pe drept."},{"v":17,"t":"Căci ce împărat dintre cei ce au trăit vreodată a dobândit o asemenea virtute încât să umple urechile și limbile tuturor oamenilor de pe pământ cu propriul lui nume? Ce împărat, după ce a rânduit legi atât de cucernice și înțelepte, le-a întins de la un capăt al pământului la celălalt, așa încât sunt citite neîncetat în auzul tuturor oamenilor?"},{"v":18,"t":"Cine a desființat obiceiurile barbare și sălbatice ale neamurilor necivilizate prin legile Lui blânde și prea filantropice? Cine, fiind atacat veacuri întregi de toți, a arătat o virtute supraomenească atât de mare încât înflorește zilnic și rămâne tânăr toată viața Lui?"},{"v":19,"t":"Cine a întemeiat un neam care din vechime nici nu se auzea, dar care acum nu este ascuns într-un colț al pământului, ci este răspândit pretutindeni sub soare? Cine și-a întărit atât de bine ostașii cu armele cucerniciei încât sufletele lor, fiind mai tari decât diamantul, strălucesc minunat în luptele cu potrivnicii lor?"},{"v":20,"t":"Ce împărat biruie într-atât și, chiar după moarte, își conduce ostașii și ridică trofee peste dușmanii săi și umple fiecare loc, țară și cetate, greacă și barbară, cu locuințele Lui împărătești, chiar cu temple dumnezeiești cu prinoasele lor sfințite, ca însuși acest templu cu podoabele lui minunate și darurile de închinare, care sunt ele însele cu adevărat mari și maiestuoase, vrednice de mirare și admirație, și semne limpezi ale stăpânirii Mântuitorului nostru? Căci și acum «a grăit și s-au făcut; a poruncit și au fost create». Căci ce era care să se împotrivească semnului Împăratului și Cârmuitorului universal și Cuvântului lui Dumnezeu însuși?"},{"v":21,"t":"Ar fi nevoie de o cuvântare deosebită pentru a trece în revistă și a explica exact toate acestea; și, de asemenea, pentru a descrie cât de mare este socotită de El, cel sărbătorit ca dumnezeiesc, râvna lucrătorilor, El, care privește templul viu pe care îl alcătuim toți, și cercetează casa, alcătuită din pietre vii și mișcătoare, bine și sigur zidită pe temelia apostolilor și proorocilor, piatra din capul unghiului fiind Isus Hristos însuși, care a fost respins nu numai de zidarii acelei clădiri vechi care nu mai stă în picioare, ci și de zidarii — arhitecți răi ai unor lucrări rele — ai zidirii care este alcătuită din mulțimea oamenilor și încă dăinuie. Dar Tatăl L-a aprobat și atunci, și acum, și L-a făcut capul unghiului acestei biserici comune a noastre."},{"v":22,"t":"Cine, privind acest templu viu al Dumnezeului celui viu, alcătuit din noi înșine — acest sanctuar prea mare și cu adevărat dumnezeiesc, zic, ale cărui altare cele mai lăuntrice sunt nevăzute mulțimii și sunt cu adevărat sfinte și sfânta sfintelor — ar cuteza să-l descrie? Cine este în stare să privească măcar înăuntrul incintei sfinte, în afară de marele Arhiereu al tuturor, căruia singur i se îngăduie să pătrundă tainele fiecărui suflet rațional?"},{"v":23,"t":"Dar poate i se îngăduie altuia, unuia singur, să fie al doilea după El în aceeași lucrare, anume comandantului acestei armate, pe care primul și marele Arhiereu însuși l-a cinstit cu locul al doilea în acest sanctuar, păstorul turmei voastre dumnezeiești, care a dobândit poporul vostru prin sortul și judecata Tatălui, ca și cum l-ar fi rânduit slujitor și tâlcuitor al Său, un nou Aaron sau Melhisedec, făcut asemenea Fiului lui Dumnezeu, rămânând și fiind păzit neîncetat de El, potrivit rugăciunilor unite ale voastre ale tuturor."},{"v":24,"t":"Lui singur, deci, să i se îngăduie, dacă nu în primul rând, cel puțin în al doilea după primul și marele Arhiereu, să observe și să supravegheze starea cea mai lăuntrică a sufletelor voastre — lui, care prin experiență și lungimea timpului a încercat exact pe fiecare și care prin râvna și grija lui v-a rânduit pe toți în purtare și învățătură cucernică și este mai în stare decât oricine altul să dea o socoteală, pe măsura faptelor, despre cele pe care el însuși le-a săvârșit cu ajutorul Dumnezeiesc."},{"v":25,"t":"Cât despre primul și marele nostru Arhiereu, se spune: «Orice vede că face Tatăl, aceleași le face și Fiul.» (Ioan 5:19) Tot așa și acesta, privind spre El ca spre primul învățător, cu ochii curați ai minții, folosind ca arhetipuri tot ce vede că face El, produce chipuri ale lor, făcându-le, pe cât este cu putință, în aceeași asemănare, întru nimic mai prejos decât acel Beseleel, pe care Dumnezeu însuși l-a «umplut cu duhul înțelepciunii și priceperii» (Exod 35:31) și cu alte cunoștințe tehnice și științifice și l-a chemat să fie făcătorul templului construit după tipare cerești date în simboluri."},{"v":26,"t":"Astfel și acesta, purtând în propriul său suflet chipul lui Hristos întreg, Cuvântul, Înțelepciunea, Lumina, a alcătuit acest templu măreț al Dumnezeului celui preaînalt, corespunzând modelului celui mai mare ca un lucru văzut unuia nevăzut; este cu neputință de spus cu câtă mărime de suflet, cu câtă bogăție și largheță de minte și cu câtă întrecere din partea voastră a tuturor, arătată în noblețea celor care au contribuit, care s-au străduit cu ambiție să nu rămână cu nimic în urma lui în împlinirea aceluiași scop. Și acest loc — căci aceasta merită pomenită înaintea tuturor — care fusese acoperit cu tot felul de gunoaie prin meșteșugurile dușmanilor noștri, el nu l-a trecut cu vederea și nici nu a cedat răutății celor care au adus acea stare de lucruri, deși ar fi putut alege un alt loc, căci erau multe alte terenuri disponibile în cetate, unde ar fi avut mai puțină osteneală și ar fi fost scutit de supărare."},{"v":27,"t":"Dar trezindu-se mai întâi la lucru și apoi întărind tot poporul cu râvnă și alcătuindu-i pe toți într-un singur trup mare, a purtat prima luptă. Căci socotea că această biserică, care fusese deosebit de asediată de dușman, care suferise cea dintâi și îndurase aceleași prigoane cu noi și pentru noi, ca o mamă lipsită de copiii ei, trebuia să se bucure cu noi de binevoința deosebită a prea milostivului Dumnezeu."},{"v":28,"t":"Căci atunci când Marele Păstor a izgonit fiarele sălbatice și lupii și orice fiară cruntă și sălbatică și, după cum spun dumnezeieștile oracole, «a zdrobit fălcile leilor», a găsit cu cale să-i adune iarăși copiii în același loc și, în chipul cel mai drept, a așezat staulul turmei ei, «ca să facă de rușine pe dușman și pe răzbunător» și să respingă îndrăzneala nelegiuită a dușmanilor lui Dumnezeu."},{"v":29,"t":"Și acum ei nu mai sunt — urâtorii de Dumnezeu — căci nu au fost niciodată. După ce au tulburat și au fost tulburați un timp scurt, au suferit pedeapsa cuvenită și s-au adus pe sine, pe prietenii și pe rudele lor la totală nimicire, așa încât declarațiile înscrise din vechime în însemnările sfinte au fost dovedite adevărate prin fapte. În aceste declarații cuvântul dumnezeiesc spune cu adevărat, printre altele, următoarele despre ei:"},{"v":30,"t":"«Cei răi au scos sabia, și-au încordat arcul, ca să omoare pe cei drepți la inimă; sabia lor să intre în inima lor și arcurile lor să se frângă.» Și iarăși: «Pomenirea lor a pierit cu zgomot» și «numele lor l-ai șters în veci de veci»; căci și ei, când erau în necaz, «au strigat și nu era cine să-i mântuiască: către Domnul, și nu i-a ascultat.» Dar «picioarele lor au fost legate laolaltă și au căzut, dar noi ne-am ridicat și stăm drepți.» Și ce se vestise mai dinainte în aceste cuvinte — «Doamne, în cetatea Ta vei face de nimic chipul lor» — s-a arătat adevărat ochilor tuturor."},{"v":31,"t":"Dar după ce au purtat război ca uriașii împotriva lui Dumnezeu, au murit în acest chip. Iar cea pustiită și respinsă de oameni a primit desăvârșirea pe care o vedem, în urma răbdării ei față de Dumnezeu, așa încât proorocia lui Isaia a fost spusă despre ea:"},{"v":32,"t":"«Bucură-te, pustiu însetat, să se bucure pustiul și să înflorească ca crinul, și locurile pustii vor înflori și se vor veseli.» (Isaia 35:1) «Întăriți-vă, mâini slabe și genunchi sleiți. Îmbărbătați-vă, voi cei slabi la inimă, în mințile voastre; fiți tari, nu vă temeți. Iată, Dumnezeul nostru răsplătește judecata și va răsplăti, va veni și ne va mântui.» «Căci», spune el, «în pustie a izbucnit apă și un iaz în pământ însetat, și țara uscată va fi pajiști cu ape și în pământul însetat vor fi izvoare de apă.»"},{"v":33,"t":"Aceste lucruri prorocite de demult au fost înregistrate în cărți sfinte; dar nu ne sunt transmise acum numai din auzite, ci în fapte. Acest pustiu, acest pământ uscat, această văduvă și părăsită, «ale cărei porți le-au tăiat cu securi ca lemnul din pădure, pe care au doborât-o cu topor și ciocan», ale cărei cărți au nimicit-o de asemenea, «ardând cu foc sanctuarul lui Dumnezeu și spurcând la pământ locașul numelui Lui», «pe care au jefuit-o toți cei ce treceau pe cale și ale cărei garduri le-au dărâmat, pe care a pustiit-o mistrețul din pădure și din care s-a hrănit fiara sălbatică», acum, prin puterea minunată a lui Hristos, când voiește El, a devenit ca un crin. Căci și atunci a fost pedepsită la semnul Lui ca de un tată grijuliu; «căci pe cine iubește Domnul îl pedepsește și bate pe tot fiul pe care îl primește»."},{"v":34,"t":"Apoi, după ce a fost pedepsită într-o măsură, după nevoile cazului, i se poruncește să se bucure din nou; și înflorește ca un crin și răspândește mirosul ei dumnezeiesc între toți oamenii. «Căci», se spune, «a izbucnit apă în pustie» (Isaia 35:6), izvorul băii mântuitoare a nașterii din nou dumnezeiești. Și acum ea, care cu puțin înainte era un pustiu, «a devenit pajiști cu ape, și izvoare de apă au țâșnit în pământ însetat». (Isaia 35:7) Mâinile care înainte erau «slabe» au devenit «cu adevărat tari»; și aceste lucrări sunt dovezi mari și convingătoare ale mâinilor tari. Genunchii, de asemenea, care înainte erau «sleiți și neputincioși», recăpătându-și puterea obișnuită, merg drept înainte pe calea cunoașterii dumnezeiești și se grăbesc spre turma înrudită a prea binevoitorului Păstor."},{"v":35,"t":"Și dacă sunt unii ale căror suflete au fost amorțite de amenințările tiranilor, nici aceștia nu sunt trecuți cu vederea ca nevindecabili de Cuvântul mântuitor; ci îi vindecă și pe ei și îi îndeamnă să primească mângâierea dumnezeiască, zicând: «Mângâiați-vă, voi cei slabi la inimă; întăriți-vă, nu vă temeți.» (Isaia 35:4)"},{"v":36,"t":"Acest nou și ales Zorobabel al nostru, auzind cuvântul care vestise mai dinainte că cea făcută pustiu pentru Dumnezeu se va bucura de aceste lucruri, după amara robie și urâciunea pustiirii, nu a trecut cu vederea trupul mort; ci mai întâi, cu rugăciuni și cereri, a îmblânzit pe Tatăl cu învoirea comună a voastră a tuturor și, chemând ca aliat și împreună-lucrător pe singurul care dă viață morților, a ridicat-o pe cea căzută, după ce a curățit-o și a eliberat-o de relele ei. Și a îmbrăcat-o nu cu haina cea veche, ci cu una cum a învățat din nou din dumnezeieștile oracole, care spun limpede: «Și slava de pe urmă a acestei case va fi mai mare decât cea dintâi.» (Hagai 2:9)"},{"v":37,"t":"Astfel, cuprinzând un spațiu mult mai mare, a întărit curtea exterioară cu un zid care înconjura totul, care să slujească drept cel mai sigur bastion pentru întreaga clădire."},{"v":38,"t":"Și a ridicat și a întins un vestibul mare și înalt spre razele soarelui răsărind și a dat celor care stăteau departe în afara incintei sfinte o vedere deplină asupra celor dinăuntru, întorcând aproape ochii celor străini de credință spre intrări, așa încât nimeni nu putea trece fără să fie impresionat de amintirea pustiirii de mai înainte și a prefacerii de acum de necrezut. Nădejdea lui era ca unul ca acesta, impresionat de aceasta, să fie atras și îndemnat să intre prin însăși vederea."},{"v":39,"t":"Dar când cineva ajunge înăuntrul porților, nu îl lasă să intre îndată în sanctuar cu picioare necurate și nespălate; ci lăsând cât mai mult spațiu cu putință între templu și intrarea exterioară, l-a înconjurat și l-a împodobit cu patru galerii transversale, făcând un spațiu pătrat cu stâlpi ridicându-se pe toate laturile, pe care i-a unit cu paravane de lemn în formă de zăbrele, ridicate la o înălțime potrivită; și a lăsat un spațiu deschis la mijloc, ca să se vadă cerul și aerul liber, strălucitor în razele soarelui."},{"v":40,"t":"Aici a pus simboluri ale curățirilor sfinte, ridicând fântâni în fața templului care dau îmbelșugat apă, cu care cei care intră în sanctuar se pot curăți. Aceasta este prima oprire a celor care intră; și dă totodată o priveliște frumoasă și strălucită oricui și un loc potrivit celor care au încă nevoie de învățătură elementară."},{"v":41,"t":"Dar trecând de acest spectacol, a făcut intrări deschise în templu cu multe alte vestibule înăuntru, punând trei uși pe o latură, tot spre razele soarelui. Pe cea din mijloc, împodobită cu plăci de bronz, legată cu fier și frumos ciocănită, a făcut-o mult mai înaltă și mai largă decât celelalte, ca și cum le-ar fi făcut pe acelea păzitoare pentru ea ca pentru o regină."},{"v":42,"t":"În același chip, rânduind numărul vestibulelor pentru culoarele de pe fiecare parte a întregului templu, a făcut deasupra lor diferite deschizături în clădire, în scopul de a primi mai multă lumină, împodobindu-le cu o foarte frumoasă lucrătură în lemn. Iar casa împărătească a înzestrat-o cu materiale mai frumoase și mai strălucitoare, folosind largheță nestingherită în cheltuielile lui."},{"v":43,"t":"Mi se pare de prisos să descriu aici în amănunt lungimea și lățimea clădirii, strălucirea și maiestatea ei care întrec orice descriere și înfățișarea strălucitoare a lucrării, turnurile ei înalte ajungând la ceruri și cedrii scumpi ai Libanului de deasupra lor, pe care oracolul dumnezeiesc nu a uitat să-i pomenească, zicând: «Copacii Domnului se vor bucura și cedrii Libanului pe care i-a sădit.»"},{"v":44,"t":"De ce să descriu acum rânduiala iscusită a arhitecturii și frumusețea nespusă a fiecărei părți, când mărturia ochiului face de prisos învățătura prin ureche? Căci după ce a încheiat astfel templul, l-a înzestrat cu tronuri înalte în cinstea celor care păstoresc și, în plus, cu scaune așezate în ordinea cuvenită în toată clădirea și, în sfârșit, a pus la mijloc sfânta sfintelor, altarul, și, pentru ca să fie inaccesibil mulțimii, l-a închis cu zăbrele de lemn lucrate cu exactitate cu sculptură artistică, înfățișând o priveliște minunată privitorilor."},{"v":45,"t":"Și nici pardoseala nu a fost neglijată de el; căci și pe aceasta a împodobit-o cu marmură frumoasă de orice fel. Apoi a trecut în sfârșit la părțile din afara templului, făcând exedre spațioase și clădiri pe fiecare parte, care erau unite cu bazilica și comunicau cu intrările spre interiorul clădirii. Acestea au fost ridicate de prea pașnicul nostru Solomon, făcătorul templului lui Dumnezeu, pentru cei care aveau încă nevoie de curățire și stropire cu apă și cu Duhul Sfânt, așa încât proorocia citată mai sus nu mai este doar un cuvânt, ci o faptă; căci acum s-a întâmplat și că în adevăr «slava de pe urmă a acestei case este mai mare decât cea dintâi». (Hagai 2:9)"},{"v":46,"t":"Căci era necesar și cuvenit ca, precum păstorul și Domnul ei gustase odată moartea pentru ea și, după patima Lui, schimbase acel trup josnic pe care îl luase în favoarea ei într-un trup strălucitor și slăvit, ducând însăși carnea izbăvită din stricăciune la nestricăciune, și ea să se bucure de rânduielile Mântuitorului. Căci primind de la El făgăduința unor lucruri mult mai mari decât acestea, dorește să aibă parte neîntrerupt, în veșnicie, împreună cu corul îngerilor luminii, în slava mult mai mare a nașterii din nou, (Matei 19:28) în învierea unui trup nestricăcios, în palatul lui Dumnezeu dincolo de ceruri, cu însuși Isus Hristos, Binefăcătorul și Mântuitorul universal."},{"v":47,"t":"Dar deocamdată, cea care odinioară era văduvă și pustie este îmbrăcată prin harul lui Dumnezeu cu aceste flori și a devenit cu adevărat ca un crin, după cum spune proorocia, și, primind haina de mireasă și cununa frumuseții, este învățată de Isaia să danseze și să aducă mulțumirile ei lui Dumnezeu Împăratul în cuvinte reverențioase."},{"v":48,"t":"Să o auzim spunând: «Sufletul meu se va bucura în Domnul; căci m-a îmbrăcat cu haina mântuirii și cu mantia bucuriei; m-a împodobit ca pe un mire cu o cunună și m-a împodobit ca pe o mireasă cu juvaeruri; și precum pământul care scoate mugurul lui și precum o grădină care face să încolțească cele semănate în ea, tot așa Domnul Dumnezeu a făcut să încolțească dreptatea și lauda înaintea tuturor neamurilor.» (Isaia 61:10-11)"},{"v":49,"t":"În aceste cuvinte se bucură ea. Și în cuvinte asemănătoare îi răspunde mirele ceresc, Cuvântul Isus Hristos însuși. Ascultați pe Domnul zicând: «Nu te teme că ai fost făcută de rușine, nici nu te tulbura că ai fost certată; căci vei uita rușinea de mai înainte și ocara văduviei tale nu ți-o vei mai aminti.» «Nu ca pe o femeie părăsită și slabă la inimă te-a chemat Domnul, nici ca pe o femeie urâtă din tinerețe, zice Dumnezeul tău. Pentru un mic moment te-am părăsit, dar cu mare milă mă voi îndura de tine; într-o mică mânie mi-am ascuns fața de tine, dar cu milă veșnică mă voi îndura de tine, zice Domnul care te-a răscumpărat.» (Isaia 54:6-8)"},{"v":50,"t":"«Deșteaptă-te, deșteaptă-te, tu care ai băut din mâna Domnului paharul urgiei Lui; căci ai băut paharul pieirii, potirul mâniei Mele, și l-ai golit. Și nu era cine să te mângâie dintre toți fiii tăi pe care i-ai născut și nu era cine să te ia de mână.» «Iată, am luat din mâna ta paharul pieirii, potirul urgiei Mele, și nu vei mai bea din el. Și îl voi pune în mâinile celor care te-au nedreptățit și te-au smerit.»"},{"v":51,"t":"«Deșteaptă-te, deșteaptă-te, îmbracă-te cu puterea ta, îmbracă-te cu slava ta. Scutură praful și ridică-te. Așază-te, dezleagă legăturile gâtului tău.» «Ridică-ți ochii de jur împrejur și vezi pe copiii tăi adunați laolaltă; iată, s-au adunat laolaltă și au venit la tine. Precum eu trăiesc, zice Domnul, te vei îmbrăca cu ei toți ca cu o podoabă și te vei încinge cu ei ca cu podoabele unei mirese. Căci locurile tale pustiite și stricate și ruinate vor fi acum prea strâmte din pricina celor care te locuiesc, iar cei care te înghițeau vor fi departe de tine."},{"v":52,"t":"Căci fiii tăi pe care i-ai pierdut vor spune în urechile tale: Locul este prea strâmt pentru mine, dă-mi loc să locuiesc. Atunci vei zice în inima ta: Cine mi i-a născut pe aceștia? Eu sunt fără copii și văduvă, și cine mi i-a crescut pe aceștia? Eu rămăsesem singură și aceștia, unde erau pentru mine?»"},{"v":53,"t":"Acestea sunt lucrurile pe care le-a prevestit Isaia; și care au fost înregistrate din vechime despre noi în cărți sfinte și era necesar să aflăm cândva adevărul lor prin împlinire."},{"v":54,"t":"Căci atunci când mirele, Cuvântul, a adresat o asemenea limbă propriei sale mirese, sfintei și sfintei Biserici, acest prieten al mirelui — când ea era pustiită și zăcea ca un cadavru, lipsită de nădejde în ochii oamenilor — potrivit rugăciunilor unite ale voastre ale tuturor, cum se cuvenea, și-a întins mâinile și a trezit-o și a ridicat-o la porunca lui Dumnezeu, Împăratul universal, și la arătarea puterii lui Isus Hristos; și ridicând-o, a întemeiat-o după cum învățase din descrierea dată în dumnezeieștile oracole."},{"v":55,"t":"Aceasta este, într-adevăr, o minune foarte mare, care întrece orice admirație, mai ales pentru cei care iau seama doar la înfățișarea exterioară; dar mai minunate decât minunile sunt arhetipurile și prototipurile lor mintale și modelele dumnezeiești; mă refer la reproducerile zidirii insuflate și raționale din sufletele noastre."},{"v":56,"t":"Pe aceasta Fiul dumnezeiesc însuși a creat-o după chipul Său, împărtășindu-i pretutindeni și în toate privințele asemănarea cu Dumnezeu, o fire nestricăcioasă, necorporală, rațională, liberă de orice materie pământească, o ființă înzestrată cu propria ei inteligență; și după ce a chemat-o odată din neființă la ființă, a făcut-o soție sfântă, un templu prea sfânt pentru Sine și pentru Tatăl. Aceasta o declară și o mărturisește limpede în următoarele cuvinte: «Voi locui în ei și voi umbla în ei; și Eu voi fi Dumnezeul lor și ei vor fi poporul Meu.» (2 Corinteni 6:16) Astfel este sufletul desăvârșit și curățit, făcut astfel de la început să poarte chipul Cuvântului ceresc."},{"v":57,"t":"Dar când, prin invidia și râvna demonului răutăcios, ea a devenit, din propria ei alegere liberă, senzuală și iubitoare de rău, Dumnezeirea a părăsit-o; și ca lipsită de un protector, a devenit pradă ușoară și lesne accesibilă pentru cei care o invidiaseră de mult; și fiind atacată de bateriile și mașinile dușmanilor ei nevăzuți și ale vrăjmașilor duhovnicești, a suferit o cădere cumplită, așa încât în ea nu a rămas piatră de virtute peste piatră, ci a zăcut cu totul moartă pe pământ, cu desăvârșire dezbrăcată de ideile ei firești despre Dumnezeu."},{"v":58,"t":"Dar în timp ce ea, care fusese făcută după chipul lui Dumnezeu, zăcea astfel doborâtă, nu mistrețul acela din pădure pe care îl vedem a jefuit-o, ci un demon nimicitor și fiare sălbatice duhovnicești care au amăgit-o cu patimile lor ca și cu săgețile de foc ale propriei lor răutăți și au ars cu foc sanctuarul cu adevărat dumnezeiesc al lui Dumnezeu și au spurcat la pământ cortul numelui Lui. Apoi, îngropând pe cea nenorocită cu grămezi de pământ, au nimicit orice nădejde de izbăvire."},{"v":59,"t":"Dar acel Cuvânt dumnezeiesc de luminos și mântuitor, protectorul ei, după ce ea suferise pedeapsa meritată pentru păcatele ei, a restabilit-o din nou, câștigând bunăvoința prea milostivului Tată."},{"v":60,"t":"Câștigând mai întâi sufletele celor mai înalți stăpânitori, a curățit, prin lucrarea acelor prinți atât de binecuvântați de Dumnezeu, tot pământul de toți nimicitorii nelegiuiți și de înșiși tiranii cumpliți și urâtori de Dumnezeu. Apoi, scoțând la lumină pe cei ce erau prietenii Lui, care mai de mult fuseseră consacrați Lui pe viață, dar în mijlocul, ca să zic așa, al unei furtuni de rele, fuseseră ascunși sub adăpostul Lui, i-a cinstit vrednic cu marile daruri ale Duhului. Și iarăși, prin ei, a curățat și a lămurit cu lopeți și sape — cuvintele de povățuire ale învățăturii — sufletele care cu puțin înainte fuseseră acoperite de murdărie și împovărate de tot felul de materie și gunoaie ale rânduielilor nelegiuite."},{"v":61,"t":"Și când a făcut curat și limpede pământul minților voastre ale tuturor, l-a încredințat în cele din urmă acestui Cârmuitor prea înțelept și iubit de Dumnezeu, care, fiind înzestrat cu judecată și chibzuință, ca și cu alte daruri, și fiind în stare să cerceteze și să deosebească cu exactitate mințile celor încredințați grijii lui, din prima zi, ca să zic așa, până în prezent, nu a încetat să zidească."},{"v":62,"t":"Acum a pus aurul strălucitor, iarăși argintul curățit și nealiat și pietrele prețioase și scumpe în voi toți, așa încât se împlinește iarăși pentru voi în fapte o proorocie sfântă și tainică, care spune: «Iată, voi face piatra ta un carbuncul, și temeliile tale de safir, și crenelurile tale de iaspis, și porțile tale de cristale, și zidul tău de pietre alese; și toți fiii tăi vor fi învățați de Dumnezeu, și copiii tăi se vor bucura de pace deplină; și în dreptate vei fi zidită.»"},{"v":63,"t":"Zidind, deci, în dreptate, a împărțit tot poporul după puterea lui. Cu unii a întărit doar incinta exterioară, zidind-o cu credință nefățarnică; așa erau marea masă a poporului care nu era în stare să poarte o zidire mai mare. Pe alții i-a lăsat să intre în clădire, poruncindu-le să stea la ușă și să fie călăuze pentru cei care vor intra; aceștia pot fi comparați, nu nepotrivit, cu vestibulele templului. Pe alții i-a sprijinit pe primii stâlpi care sunt așezați în afară, în jurul sălii pătrate, inițiindu-i în primele elemente ale literei celor patru Evanghelii. Pe alții încă i-a unit în jurul bazilicii, pe ambele laturi; aceștia sunt catehumenii care încă înaintează și progresează și nu sunt departe de vederea cea mai lăuntrică a celor dumnezeiești acordată credincioșilor."},{"v":64,"t":"Luând dintre aceștia sufletele curate care au fost curățite ca aurul prin spălarea dumnezeiască, îi sprijină apoi pe stâlpi, cu mult mai buni decât cei din afară, făcuți din învățăturile lăuntrice și tainice ale Scripturii, și îi luminează prin ferestre."},{"v":65,"t":"Împodobind tot templul cu un mare vestibul al slavei unicului Împărat universal și singurul Dumnezeu și așezând de ambele părți ale autorității Tatălui pe Hristos și Duhul Sfânt, ca a doua lumină, arată din belșug și cu slavă în toată clădirea limpezimea și strălucirea adevărului celorlalte în toate amănuntele lui. Și alegând din toate părțile pietrele vii și mișcătoare și bine pregătite ale sufletelor, construiește din ele toate casa cea mare și împărătească, strălucitoare și plină de lumină atât înăuntru, cât și în afară; căci nu numai sufletul și înțelegerea, ci și trupul lor este făcut slăvit de podoaba înfloritoare a curăției și smereniei."},{"v":66,"t":"Și în acest templu sunt și tronuri și un mare număr de scaune și bănci, în toate acele suflete în care șed darurile Duhului Sfânt, așa cum au fost văzute odinioară de sfinții apostoli și de cei care erau cu ei, când «li s-au arătat limbi despărțite, ca de foc, și s-au așezat pe fiecare dintre ei». (Fapte 2:3)"},{"v":67,"t":"Dar în căpetenia tuturor este firesc să socotim că însuși Hristos locuiește în plinătatea Lui, iar în cei care ocupă locul al doilea după el, pe măsura în care fiecare este în stare să cuprindă puterea lui Hristos și a Duhului Sfânt. Și sufletele unora dintre aceia, anume ale celor încredințați fiecăruia dintre ei spre învățare și purtare de grijă, pot fi scaune pentru îngeri."},{"v":68,"t":"Dar marele și augustul și unicul altar, ce altceva ar putea fi decât curata sfântă a sfintelor a sufletului preotului comun al tuturor? Stând la dreapta lui, Isus însuși, marele Arhiereu al universului, Unul-Născut al lui Dumnezeu, primește cu ochi strălucitor și mână întinsă tămâia dulce de la toți și jertfele fără sânge și nemateriale aduse în rugăciunile lor și le duce Tatălui ceresc și Dumnezeului universului. Și El însuși I se închină cel dintâi și singur dă Tatălui reverența care I se cuvine, rugându-L să rămână totdeauna bun și îndurător față de noi toți."},{"v":69,"t":"Astfel este marele templu pe care marele Făcător al universului, Cuvântul, l-a zidit în toată lumea, făcându-l un chip intelectual pe pământ al celor care se află deasupra bolții cerului, ca în toată creația, inclusiv în ființele raționale de pe pământ, Tatăl Său să fie cinstit și adorat."},{"v":70,"t":"Dar regiunea de deasupra cerurilor, cu modelele lucrurilor pământești care sunt acolo, și așa-numitul Ierusalim de sus, și muntele ceresc al Sionului, și cetatea mai presus de lume a Dumnezeului celui viu, în care nenumărate cete de îngeri și Biserica celor întâi-născuți, ale căror nume sunt scrise în ceruri, (Evrei 12:22-23) laudă pe Făcătorul lor și pe Stăpânul suprem al universului cu imnuri de laudă de nespus și de neînțeles pentru noi — cine dintre muritori este în stare să o sărbătorească vrednic? «Căci ochiul n-a văzut, urechea n-a auzit și la inima omului nu s-au suit lucrurile pe care Dumnezeu le-a pregătit celor ce Îl iubesc.» (1 Corinteni 2:9)"},{"v":71,"t":"Fiindcă noi, bărbați, copii și femei, mici și mari, suntem deja în parte părtași ai acestor lucruri, să nu încetăm toți împreună, cu un singur duh și un singur suflet, să mărturisim și să lăudăm pe autorul unor binefaceri atât de mari pentru noi, «Cel ce iartă toate nelegiuirile noastre, Cel ce vindecă toate bolile noastre, Cel ce izbăvește din pieire viața noastră, Cel ce ne încununează cu milă și îndurare, Cel ce satură dorințele noastre cu bunătăți.» «Căci nu ne-a făcut după păcatele noastre, nici nu ne-a răsplătit după nelegiuirile noastre;» «căci cât de departe este răsăritul de apus, atât de departe a depărtat de la noi nelegiuirile noastre. Precum un tată se îndură de copiii săi, așa se îndură Domnul de cei ce se tem de El.»"},{"v":72,"t":"Aprinzând din nou aceste gânduri în amintirile noastre, și acum, și în tot timpul ce va să vină, și contemplând în minte, noapte și zi, în fiecare ceas și cu fiecare suflare, ca să zic așa, pe Autorul și Stăpânul sărbătorii de față și al acestei zile strălucitoare și prea luminoase, să-L iubim și să-L adorăm cu toată puterea sufletului. Și acum, ridicându-ne, să-L rugăm cu glas tare să ne adăpostească și să ne păzească până la sfârșit în staulul Lui, dăruind pacea Sa neîntreruptă și neclintită pe vecie, în Hristos Isus Mântuitorul nostru; prin care fie Lui slava în vecii vecilor. Amin."}];
window.LIB_LAZY["eusebiu-istoria#252"]=[{"v":1,"t":"Să adăugăm în sfârșit traducerile din limba romană ale decretelor imperiale ale lui Constantin și Licinius."},{"v":2,"t":"Copie a decretelor imperiale traduse din limba romană: Văzând de mult că libertatea religioasă nu trebuie refuzată, ci că trebuie lăsat la judecata și dorința fiecărui om să-și îndeplinească îndatoririle religioase după propria alegere, dăduserăm porunci ca fiecare om, creștini ca și ceilalți, să păstreze credința propriei sale secte și religii."},{"v":3,"t":"Dar fiindcă în acel rescript, în care li se acorda o asemenea libertate, păreau adăugate în mod vădit multe și felurite condiții, unii dintre ei, poate, după puțin timp s-au retras de la o asemenea păzire."},{"v":4,"t":"Când eu, Constantin Augustus, și eu, Licinius Augustus, am venit sub auspicii favorabile la Milan și am luat în considerare tot ce ținea de binele comun și de prosperitate, am hotărât printre altele, sau mai bine zis mai întâi de toate, să dăm asemenea decrete care păreau în multe privințe spre folosul fiecăruia; anume, care să păstreze reverența și cucernicia față de dumnezeire. Am hotărât, adică, să acordăm atât creștinilor, cât și tuturor oamenilor libertatea de a urma religia pe care o aleg, pentru ca orice dumnezeire cerească există să ne fie îndurătoare nouă și tuturor celor care trăiesc sub cârmuirea noastră."},{"v":5,"t":"Am hotărât, deci, cu scop sănătos și drept, că libertatea nu trebuie refuzată nimănui de a alege și a urma practicile religioase ale creștinilor, ci că fiecăruia trebuie să i se dea libertatea de a-și dedica mintea acelei religii pe care o socotește potrivită pentru sine, pentru ca Dumnezeirea să ne arate în toate grija și bunăvoința Ei obișnuită."},{"v":6,"t":"Se cuvenea să scriem că aceasta este voința noastră, ca acele condiții fiind cu totul lăsate la o parte, care erau cuprinse în scrisoarea noastră de mai înainte privind pe creștini, care a fost trimisă devotamentului tău, tot ce părea foarte aspru și străin de blândețea noastră să fie anulat și acum fiecare care are aceeași dorință de a păzi religia creștinilor să o poată face fără a fi supărat."},{"v":7,"t":"Am hotărât să comunicăm aceasta cât se poate de pe deplin grijii tale, pentru ca să știi că am acordat acelorași creștini libertate și deplină slobozenie de a-și păzi propria religie."},{"v":8,"t":"Fiindcă aceasta le-a fost acordată de noi cu largheță, devotamentul tău vede că libertatea se acordă și altora care ar voi să-și urmeze propriile practici religioase; fiind în mod vădit în acord cu liniștea vremurilor noastre ca fiecare să aibă libertatea de a alege și a cinsti orice dumnezeire îi place. Aceasta s-a făcut de noi pentru ca să nu părem că discriminăm în vreun chip vreun rang sau vreo religie."},{"v":9,"t":"Și mai decretăm în privința creștinilor că locurile lor, în care erau deprinși mai înainte să se adune și în privința cărora s-a dat o poruncă diferită în scrisoarea de mai înainte trimisă devotamentului tău, dacă se arată că le-a cumpărat cineva fie de la vistieria noastră, fie de la altă persoană, să fie restituite zișilor creștini, fără a cere bani sau vreun alt echivalent, fără zăbavă sau șovăire."},{"v":10,"t":"Dacă vreunii au primit în dar zisele locuri, să le restituie cât mai repede acelorași creștini: cu înțelegerea că, dacă cei care au cumpărat aceste locuri sau cei care le-au primit în dar cer ceva din darnicia noastră, să meargă la judecătorul ținutului, pentru ca prin îndurarea noastră să se aibă grijă de ei. Toate acestea trebuie acordate societății creștinilor prin grija ta îndată și fără nicio zăbavă."},{"v":11,"t":"Și fiindcă se știe că zișii creștini au stăpânit nu numai acele locuri în care erau deprinși să se adune, ci și alte locuri, aparținând nu unor indivizi dintre ei, ci societății ca întreg, adică societății creștinilor, vei porunci ca toate acestea, în virtutea legii pe care am arătat-o mai sus, să fie restituite, fără nicio șovăire, acelorași creștini; adică societății și congregației lor: fiind păzită, desigur, dispoziția amintită mai sus, ca cei care le restituie fără plată, cum am spus mai înainte, să poată aștepta despăgubire din darnicia noastră."},{"v":12,"t":"În toate acestea, spre folosul pomenitei societăți a creștinilor, trebuie să folosești cea mai mare sârguință, pentru ca porunca noastră să fie împlinită repede și pentru ca și în aceasta, prin îndurarea noastră, să se poarte grijă de liniștea comună și publică."},{"v":13,"t":"Căci prin aceasta, după cum am spus mai înainte, bunăvoința dumnezeiască față de noi, pe care am încercat-o deja în multe privințe, va rămâne sigură în tot timpul."},{"v":14,"t":"Și pentru ca cuprinsul acestei binevoitoare rânduieli a noastre să fie cunoscut tuturor, se așteaptă ca ceea ce am scris să fie publicat pretutindeni de tine și adus la cunoștința tuturor, ca această binevoitoare rânduială a noastră să nu rămână necunoscută nimănui."},{"v":15,"t":"Copie a altui decret imperial dat de ei, arătând că îngăduința s-a acordat numai Bisericii Catolice: Salutare ție, prea stimatule Anulin. Este obiceiul bunăvoinței noastre, prea stimatule Anulin, să voim ca lucrurile care aparțin de drept altuia să nu fie doar lăsate nesupărate, ci să fie și restituite."},{"v":16,"t":"De aceea este voința noastră ca, atunci când primești această scrisoare, dacă vreunele dintre asemenea lucruri au aparținut Bisericii Catolice a creștinilor, în vreo cetate sau alt loc, dar sunt acum stăpânite de cetățeni sau de alții, să le faci să fie restituite îndată zișilor biserici. Căci am hotărât deja ca cele pe care aceleași biserici le-au stăpânit mai înainte să le fie restituite."},{"v":17,"t":"Fiindcă, deci, devotamentul tău vede că această poruncă a noastră este cât se poate de lămurită, grăbește-te să le restitui cât mai repede tot ce a aparținut mai înainte zișilor biserici, — fie grădini, fie clădiri, fie orice ar fi — pentru ca să aflăm că ai ascultat cu cea mai mare grijă de acest decret al nostru. Sănătate, prea stimatul și iubitul nostru Anulin."},{"v":18,"t":"Copie a unei epistole în care împăratul poruncește ca un sinod al episcopilor să se țină la Roma pentru unitatea și buna înțelegere a bisericilor: Constantin Augustus către Miltiade, episcopul Romei, și către Marcu. Fiindcă mi-au fost trimise multe asemenea comunicări de Anulin, prea strălucitul proconsul al Africii, în care se spune că Cecilian, episcopul cetății Cartagina, a fost acuzat de unii dintre colegii lui din Africa, în multe chestiuni; și fiindcă mi se pare un lucru foarte grav că în acele provincii pe care Purtarea de grijă dumnezeiască le-a încredințat cu largheță devotamentului meu și în care este o populație numeroasă, mulțimea se găsește urmând calea mai josnică și împărțindu-se, ca să zic așa, în două partide, iar episcopii sunt în neînțelegere —"},{"v":19,"t":"mi s-a părut bine ca Cecilian însuși, cu zece dintre episcopii care par să-l acuze și cu alți zece pe care îi va socoti necesari pentru apărarea sa, să navigheze la Roma, pentru ca acolo, în prezența voastră și a lui Reticiu, Materne și Marin, colegii voștri, pe care le-am poruncit să se grăbească la Roma în acest scop, să fie ascultat, cum veți înțelege că este în acord cu prea sfânta lege."},{"v":20,"t":"Dar pentru ca să puteți avea cunoașterea cea mai desăvârșită a tuturor acestor lucruri, am atașat la scrisoarea mea copii ale documentelor trimise mie de Anulin și le-am trimis pomeniților voștri colegi. Când fermitatea voastră le va fi citit, veți socoti în ce chip pomenitul caz poate fi cercetat cu cea mai mare exactitate și judecat cu dreptate. Căci nu scapă sârguinței voastre că am o asemenea reverență față de legitima Biserică Catolică încât nu vreau să lăsați schismă sau dezbinare în niciun loc. Dumnezeirea marelui Dumnezeu să vă păzească, prea cinstiților domni, ani mulți. Copie a unei epistole în care împăratul poruncește să se țină un alt sinod pentru a îndepărta toate neînțelegerile dintre episcopi."},{"v":21,"t":"Constantin Augustus către Crest, episcopul Siracuzei. Când unii au început, în chip rău și răzvrătit, să fie în neînțelegere între ei în privința sfintei închinări și a puterii cerești și a învățăturii catolice, voind să pun capăt unor asemenea certuri între ei, am poruncit mai înainte ca anumiți episcopi să fie trimiși din Galia și ca părțile potrivnice, care se luptau stăruitor și neîncetat între ele, să fie chemate din Africa; pentru ca în prezența lor și în prezența episcopului Romei chestiunea care părea să pricinuiască tulburarea să fie cercetată și hotărâtă cu toată grija."},{"v":22,"t":"Dar fiindcă, după cum se întâmplă, unii, uitând atât de propria lor mântuire, cât și de reverența datorată prea sfintei religii, nu pun nici acum capăt ostilităților și nu voiesc să se conformeze judecății deja date și afirmă că cei care și-au exprimat părerile și hotărârile erau puțini, sau că au fost prea grăbiți și precipitați în a da judecata, înainte de a fi cercetate toate lucrurile care trebuiau cercetate cu exactitate — din toată această pricină s-a întâmplat că chiar aceia care ar trebui să aibă relații frățești și armonioase unii cu alții sunt rușinos, sau mai bine zis scârbos, dezbinați între ei și dau prilej de batjocură acelor oameni ale căror suflete sunt străine acestei prea sfinte religii. De aceea mi s-a părut necesar să rânduiesc ca această dezbinare, care ar fi trebuit să înceteze după ce judecata fusese deja dată cu învoirea lor voluntară, să fie acum, dacă este cu putință, adusă la sfârșit prin prezența multora."},{"v":23,"t":"Fiindcă, deci, am poruncit unui număr de episcopi din foarte multe locuri diferite să se adune în cetatea Arles, înainte de calendele lui august, am socotit potrivit să scriu și ție să obții de la prea strălucitul Latronian, corector al Siciliei, un vehicul public și să iei cu tine alți doi de rangul al doilea, pe care îi vei alege tu însuți, împreună cu trei slujitori care să te slujească pe drum, și să te îndrepți spre locul pomenit înainte de ziua rânduită; pentru ca prin fermitatea ta și prin înțeleapta unanimitate și armonie a celorlalți de față, această ceartă, care a continuat rușinos până în ziua de azi în urma unor certuri rușinoase, după ce se va fi auzit tot ce au de spus cei care sunt acum în dezacord unii cu alții și pe care i-am poruncit de asemenea să fie de față, să poată fi aplanată în acord cu credința cuvenită, și armonia frățească, deși doar treptat, să fie restabilită."},{"v":24,"t":"Dumnezeu Atotțiitorul să te păzească sănătos ani mulți."}];
window.LIB_LAZY["eusebiu-istoria#253"]=[{"v":1,"t":"Constantin Augustus către Cecilian, episcopul Cartaginei. Fiindcă este plăcerea noastră să se acorde ceva în toate provinciile Africii, Numidiei și Mauritaniei unor slujitori ai legitimei și prea sfintei religii catolice, spre acoperirea cheltuielilor lor, i-am scris lui Urs, prea strălucitul ministru de finanțe al Africii, și l-am îndrumat să rânduiască să se plătească fermității tale trei mii de foles."},{"v":2,"t":"Tu, deci, după ce vei fi primit suma de bani de mai sus, poruncește să fie împărțită între toți cei pomeniți mai sus, după scurta însemnare trimisă ție de Osiu."},{"v":3,"t":"Dar dacă vei găsi că lipsește ceva pentru împlinirea acestui scop al meu în privința tuturor, vei cere fără șovăire de la Heraclid, vistiernicul nostru, tot ce vei găsi că este necesar. Căci i-am poruncit, pe când era de față, că dacă fermitatea ta îi va cere bani, să vegheze ca să fie plătiți fără zăbavă."},{"v":4,"t":"Și fiindcă am aflat că unii oameni cu mintea nestatornică voiesc să abată poporul de la prea sfânta și catolica Biserică printr-un anumit mijloc de corupție rușinoasă, să știi că am dat poruncă lui Anulin, proconsulul, și de asemenea lui Patriciu, vicarul prefecților, când erau de față, să dea atenția cuvenită nu numai altor chestiuni, ci și mai presus de toate acesteia, și să nu treacă cu vederea un asemenea lucru când se întâmplă. De aceea, dacă vei vedea pe unii asemenea oameni stăruind în această nebunie, tu să mergi fără zăbavă la pomeniții judecători și să le raportezi chestiunea; ca să-i îndrepte cum le-am poruncit când erau de față. Dumnezeirea marelui Dumnezeu să te păzească ani mulți."}];
window.LIB_LAZY["eusebiu-istoria#254"]=[{"v":1,"t":"Copie a unei epistole în care împăratul poruncește ca păstorii bisericilor să fie scutiți de toate îndatoririle politice: Salutare ție, prea stimatule Anulin. Fiindcă reiese din multe împrejurări că atunci când este disprețuită acea religie în care se păstrează reverența principală față de prea sfânta Putere cerească, vin mari primejdii peste treburile publice; dar că atunci când este îmbrățișată și păzită legal, ea dă cea mai deosebită prosperitate numelui roman și o fericire remarcabilă tuturor treburilor oamenilor, prin binefacerea dumnezeiască — mi s-a părut bine, prea stimatule Anulin, ca acei oameni care își dau slujba, cu cuvenita sfințenie și cu statornică păzire a acestei legi, închinării religiei dumnezeiești, să primească răsplată pentru osteneala lor."},{"v":2,"t":"De aceea este voința mea ca cei din provincia încredințată ție, din Biserica catolică, peste care păstorește Cecilian, care își dau slujba acestei sfinte religii și care sunt numiți de obicei clerici, să fie scutiți cu totul de toate îndatoririle publice, ca să nu fie abătuți, printr-o greșeală sau neglijență sacrilegă, de la slujba datorată Dumnezeirii, ci să se dedice fără nicio piedică propriei lor legi. Căci se pare că atunci când arată cea mai mare reverență față de Dumnezeire, cele mai mari binefaceri se revarsă asupra statului. Sănătate, prea stimatul și iubitul nostru Anulin."}];
window.LIB_LAZY["eusebiu-istoria#255"]=[{"v":1,"t":"Asemenea binecuvântări a revărsat asupra noastră harul dumnezeiesc și ceresc prin arătarea Mântuitorului nostru și așa a fost belșugul de binefaceri care a stăpânit între toți oamenii în urma păcii de care ne bucuram. Și astfel treburile noastre erau încununate cu bucurii și sărbători."},{"v":2,"t":"Dar invidia răutăcioasă și demonul care iubește răul nu au putut suporta priveliștea acestor lucruri; și, pe lângă aceasta, întâmplările petrecute cu tiranii pe care i-am pomenit deja nu au fost de ajuns să-l aducă pe Licinius la judecată sănătoasă."},{"v":3,"t":"Căci acesta din urmă, deși cârmuirea lui era prosperă și era cinstit cu rangul al doilea după marele împărat Constantin și era legat de el prin cele mai strânse legături de căsătorie, a părăsit imitarea faptelor bune și a râvnit la răutatea tiranilor nelegiuiți al căror sfârșit îl văzuse cu propriii ochi și a ales mai degrabă să urmeze principiile lor decât să rămână în relații prietenești cu cel mai bun decât ei. Invidiind pe binefăcătorul comun, a purtat împotriva lui un război nelegiuit și cât se poate de cumplit, neluând în seamă nici legile firii, nici tratatele, nici sângele și negândindu-se la legăminte."},{"v":4,"t":"Căci Constantin, ca un împărat prea binevoitor, dându-i dovezi de adevărată bunăvoință, nu a refuzat alianța cu el și nu i-a refuzat strălucita căsătorie cu sora sa, ci l-a cinstit făcându-l părtaș al nobleței strămoșești și al vechiului sânge imperial și i-a acordat dreptul de a împărți stăpânirea peste toți, ca cumnat și co-regent, încredințându-i guvernarea și administrarea unei părți nu mai mici din provinciile romane decât cea pe care o avea el însuși."},{"v":5,"t":"Dar Licinius, dimpotrivă, a urmat o cale direct opusă acesteia; făcând zilnic tot felul de uneltiri împotriva superiorului său și născocind tot felul de rău, ca să-și răsplătească binefăcătorul cu rele. La început a încercat să-și ascundă pregătirile și s-a prefăcut prieten și a practicat adesea înșelăciune și viclenie, în nădejdea că va putea împlini lesne scopul dorit."},{"v":6,"t":"Dar Dumnezeu era prietenul, protectorul și păzitorul lui Constantin și, aducând la lumină uneltirile care fuseseră urzite în taină și în întuneric, le-a zădărnicit. Atâta virtute are marea armură a cucerniciei pentru îndepărtarea dușmanilor și pentru păstrarea propriei noastre siguranțe. Apărat de aceasta, prea binecuvântatul de Dumnezeu împărat al nostru a scăpat de multele uneltiri ale omului scârbos."},{"v":7,"t":"Dar când Licinius a văzut că pregătirile lui secrete nu înaintează deloc după mintea lui — căci Dumnezeu descoperea împăratului iubit de Dumnezeu fiecare uneltire și răutate — neputând să se mai ascundă, a întreprins un război pe față."},{"v":8,"t":"Și în același timp în care a hotărât să poarte război cu Constantin, a trecut și la luptă cu Dumnezeul universului, pe care știa că Îl cinstește Constantin, și a început, încet pentru o vreme și în liniște, să atace pe supușii lui cucernici, care nu făcuseră niciodată niciun rău cârmuirii lui. Aceasta a făcut-o sub silnicia răutății lui înnăscute, care îl împingea într-o orbire cumplită."},{"v":9,"t":"Nu ținea, deci, înaintea ochilor amintirea celor care îi prigoniseră pe creștini înaintea lui și nici a celor al căror nimicitor și călău fusese rânduit, din pricina nelegiuirilor pe care le săvârșiseră. Ci îndepărtându-se de rațiunea sănătoasă, fiind cuprins, într-un cuvânt, de nebunie, a hotărât să facă război însuși lui Dumnezeu ca aliat al lui Constantin, în loc de cel ajutat de El."},{"v":10,"t":"Și mai întâi a izgonit din casa lui pe orice creștin, lipsindu-se astfel, nenorocitul, de rugăciunile pe care ei le înălțau lui Dumnezeu în favoarea lui, pe care sunt deprinși, după învățătura părinților lor, să le înalțe pentru toți oamenii. Apoi a poruncit ca soldații din cetăți să fie dați afară și lipsiți de rangul lor, dacă nu aleg să jertfească demonilor. Și totuși acestea erau lucruri mici în comparație cu cele mai mari care au urmat."},{"v":11,"t":"De ce este necesar să povestim cu de-amănuntul tot ce a făcut urâtorul de Dumnezeu și să povestim cum a născocit acest om cu totul fără lege legi nelegiuite? A dat o rânduială ca nimeni să nu arate omenie față de cei care suferă în închisoare dându-le hrană și ca nimeni să nu arate milă față de cei care pier de foame în lanțuri; ca nimeni să nu fie în niciun chip bun sau să facă vreun act bun, chiar dacă firea însăși îl mișcă să simpatizeze cu aproapele. Și aceasta era, într-adevăr, o lege pe față rușinoasă și foarte crudă, calculată să alunge orice bunătate firească. Și pe lângă aceasta s-a decretat, ca pedeapsă, ca cei care arătau compasiune să sufere aceleași lucruri cu cei pe care îi compătimeau; și ca cei care slujeau cu bunătate pe cei ce suferă să fie aruncați în lanțuri și în închisoare și să îndure aceeași pedeapsă cu cei ce suferă. Astfel erau decretele lui Licinius."},{"v":12,"t":"De ce să povestim noutățile lui privind căsătoria sau privind pe cei ce mor — noutăți prin care a cutezat să anuleze vechile legi ale romanilor, care fuseseră bine și înțelept alcătuite, și să introducă anumite legi barbare și crude, care erau cu adevărat nelegiuite și fără lege? A născocit, în paguba provinciilor care îi erau supuse, nenumărate urmăriri și tot felul de metode de stoarcere de aur și argint, noi măsurători ale pământului și stoarceri vătămătoare de la oamenii de la țară, care nu mai trăiau, ci muriseră de mult."},{"v":13,"t":"De ce este necesar să vorbim pe larg despre exilurile pe care, pe lângă aceste lucruri, acest dușman al omenirii le-a pricinuit celor care nu făcuseră niciun rău, despre izgonirile din țară ale unor oameni de neam ales și înaltă reputație, ale căror tinere soții le-a smuls de la ei și le-a dat unor oameni mai josnici de-ai săi, să fie rușinos ultragiate de ei, și despre multele femei căsătorite și fecioare cu care și-a satisfăcut poftele, deși era la vârstă înaintată — de ce, zic, este necesar să vorbim pe larg despre acestea, când răutatea excesivă a ultimelor lui fapte face ca primele să pară mici și fără însemnătate?"},{"v":14,"t":"Căci, în sfârșit, a ajuns la o asemenea culme a nebuniei încât a atacat pe episcopi, socotind că ei — ca slujitori ai Dumnezeului de peste toate — vor fi ostili măsurilor lui. Nu a procedat încă împotriva lor pe față, din frica lui de superiorul său, ci ca mai înainte, în taină și cu viclenie, folosind trădarea guvernatorilor pentru nimicirea celor mai deosebiți dintre ei. Și felul uciderii lor era ciudat și așa cum nu se mai auzise niciodată."},{"v":15,"t":"Faptele pe care le-a săvârșit la Amasia și în celelalte cetăți din Pont au întrecut orice exces de cruzime. Unele dintre bisericile lui Dumnezeu au fost din nou rase până la pământ, altele au fost închise, așa încât niciunul dintre cei deprinși să le frecventeze nu putea intra în ele și să aducă închinarea datorată lui Dumnezeu."},{"v":16,"t":"Căci conștiința lui rea îl ducea să socotească că nu se înalță rugăciuni în favoarea lui; dar era convins că noi făceam totul în interesul împăratului iubit de Dumnezeu și că ne rugam lui Dumnezeu pentru el. De aceea s-a grăbit să-și întoarcă furia împotriva noastră."},{"v":17,"t":"Și atunci cei dintre guvernatori care voiau să-l lingușească, văzând că făcând asemenea lucruri îi fac pe plac tiranului nelegiuit, au făcut pe unii dintre episcopi să sufere pedepsele aplicate de obicei criminalilor și au dus și au pedepsit fără niciun pretext, ca pe ucigași, pe cei care nu făcuseră niciun rău. Unii au îndurat acum un nou fel de moarte: trupurile lor fiind tăiate în multe bucăți cu sabia și, după acest spectacol sălbatic și cât se poate de oribil, fiind aruncați în adâncul mării ca hrană peștilor."},{"v":18,"t":"Atunci închinătorii lui Dumnezeu au fugit din nou, iar câmpurile și pustiurile, pădurile și munții i-au primit iarăși pe slujitorii lui Hristos. Și când tiranul nelegiuit a avut astfel succes în aceste măsuri, a plănuit în cele din urmă să reînnoiască prigoana împotriva tuturor."},{"v":19,"t":"Și ar fi reușit în planul său și nimic nu l-ar fi împiedicat în lucrare, dacă Dumnezeu, apărătorul vieților poporului Său, nu ar fi prevenit foarte repede ceea ce urma să se întâmple și nu ar fi făcut să strălucească o mare lumină ca în mijlocul unei nopți întunecate și posomorâte și nu ar fi ridicat un izbăvitor pentru toți, aducând în acele regiuni, cu braț înalt, pe slujitorul Său, Constantin."}];
window.LIB_LAZY["eusebiu-istoria#256"]=[{"v":1,"t":"Lui, deci, Dumnezeu i-a dat de sus, din cer, rodul meritat al cucerniciei, trofeele biruinței asupra celor nelegiuiți, și a aruncat pe cel vinovat, cu toți sfetnicii și prietenii lui, la picioarele lui Constantin."},{"v":2,"t":"Căci atunci când Licinius și-a dus nebunia la extrem, împăratul, prietenul lui Dumnezeu, socotind că nu mai trebuie îngăduit, lucrând pe temeiul unei judecăți sănătoase și amestecând principiile ferme ale dreptății cu omenia, a hotărât cu bucurie să vină în apărarea celor asupriți de tiran și s-a apucat, dând la o parte câțiva nimicitori, să mântuiască cea mai mare parte a neamului omenesc."},{"v":3,"t":"Căci atunci când mai înainte exercitase doar omenia și arătase milă celui care nu era vrednic de simpatie, nu s-a împlinit nimic; căci Licinius nu și-a lepădat răutatea, ci și-a sporit furia împotriva popoarelor care îi erau supuse și nu a rămas celor necăjiți nicio nădejde de mântuire, fiind asupriți de o fiară sălbatică."},{"v":4,"t":"De aceea, apărătorul celor virtuoși, amestecând ura față de rău cu dragostea față de bine, a ieșit cu fiul său Crisp, un prinț binefăcător, și a întins o dreaptă mântuitoare tuturor celor care pierea. Amândoi, tată și fiu, sub ocrotirea, ca să zic așa, a lui Dumnezeu, Împăratul universal, având ca și conducător și aliat pe Fiul lui Dumnezeu, Mântuitorul tuturor, și-au așezat forțele din toate părțile împotriva dușmanilor Dumnezeirii și au câștigat o biruință ușoară; Dumnezeu făcându-i să izbândească în luptă în toate după dorința lor."},{"v":5,"t":"Astfel, deodată și mai repede decât se poate povesti, cei care ieri și alaltăieri suflau moarte și amenințare nu mai erau, și nici măcar numele lor nu era pomenit, ci inscripțiile și onorurile lor au suferit dezonoarea meritată. Și ce văzuse Licinius cu propriii ochi că au venit peste tiranii nelegiuiți de mai înainte, a suferit și el, pentru că nu a primit învățătură și nu a învățat înțelepciune din pedepsele vecinilor, ci a urmat aceeași cale a nelegiuirii pe care o călcaseră ei și a fost aruncat pe drept în aceeași prăpastie. Astfel a zăcut doborât."},{"v":6,"t":"Dar Constantin, cel mai puternic biruitor, împodobit cu orice virtute a cucerniciei, împreună cu fiul său Crisp, un prinț prea iubit de Dumnezeu și în toate privințele asemenea tatălui său, a recâștigat Răsăritul care le aparținea; și au alcătuit un singur imperiu roman unit, ca odinioară, aducând sub stăpânirea lor pașnică toată lumea, de la răsăritul soarelui până la partea opusă, atât spre nord, cât și spre sud, până la marginile zilei care scade."},{"v":7,"t":"Toată teama de cei care îi necăjiseră mai înainte a fost, deci, luată de la oameni și au sărbătorit zile strălucite și de sărbătoare. Totul era plin de lumină, iar cei care înainte erau abătuți se priveau unii pe alții cu fețe zâmbitoare și ochi strălucitori. Cu dansuri și imnuri, în cetate și la țară, slăveau mai întâi de toate pe Dumnezeu, Împăratul universal, pentru că așa fuseseră învățați, și apoi pe împăratul cucernic cu copiii lui iubiți de Dumnezeu."},{"v":8,"t":"A fost uitare a relelor trecute și uitare a oricărei fapte de nelegiuire; a fost bucurie de binefacerile de acum și așteptare a celor care urmau. Edicte pline de îndurare și legi cuprinzând semne de bunăvoință și adevărată cucernicie erau date în fiecare loc de împăratul biruitor."},{"v":9,"t":"Astfel, după ce toată tirania a fost curățită, imperiul care le aparținea a fost păstrat ferm și fără rival numai pentru Constantin și fiii lui. Și ștergând fărădelegea predecesorilor lor, recunoscând binefacerile pe care le primiseră de la Dumnezeu, și-au arătat dragostea de virtute și dragostea de Dumnezeu și cucernicia și recunoștința față de Dumnezeire prin faptele pe care le-au săvârșit în vederea tuturor oamenilor. Sfârșitul, cu ajutorul lui Dumnezeu, al Cărții a zecea a Istoriei Bisericești a lui Eusebiu Pamfil."}];
